GROUPS = [
 dict(id='LEX-A1-01',title='Relações sem presumir uma família',after='A1-01',words=['neighbour','partner','parent','child'],
 situation='A recebe cartão: Lia é parent de uma child chamada Kim; Jo é neighbour de Lia; Rui é partner de Lia numa atividade de estudo. B pergunta quem é cada pessoa com Who is…? e monta uma ficha em português. A apresenta as relações em inglês. Inverta com Eva parent de Sol, Lee neighbour de Eva e Noa partner de Eva no estudo. Não pedir dados familiares reais.',
 result='Lia é mãe/pai de Kim sem gênero definido pelo termo parent; Jo é vizinho/a; Rui é parceiro/a na atividade, sem informação de casamento. Na segunda rodada: Eva/Sol, Lee vizinho/a e Noa parceiro/a de estudo. Modelo: Lia is Kim’s parent. Kim is a child. Jo is Lia’s neighbour. Rui is Lia’s partner in this activity.',
 phon='Ensaie neighbour e partner em frases com nomes. O destinatário deve distinguir a relação; ler silenciosamente não observa produção oral.',
 pitfall='Parent não traduz parente em geral; partner não comprova casamento. Ao recuperar children, distinguir plural irregular de mudança de sentido.'),
 dict(id='LEX-A1-02',title='Profissão, emprego e local de trabalho',after='A1-01',words=['teacher','nurse','driver','work','job'],
 situation='A organiza três fichas: Kim é teacher e works at a school; Jo é nurse e works at a clinic; Eva é driver e works for a bus company. B tem campos name/job/workplace e recolhe informações sem ver as fichas. Acrescente que Kim tem a second job num café e que nada informa gênero das pessoas. Apoios: clinic = clínica; bus company = empresa de ônibus; workplace = local de trabalho; second = segundo. Troquem papéis para conferir as fichas.',
 result='Kim: teacher, escola; segundo emprego num café. Jo: nurse, clínica. Eva: driver, empresa de ônibus. Modelo: Kim is a teacher. Kim works at a school. Kim has a second job at a café. Nurse/driver não fornecem gênero.',
 phon='O ouvinte separa o nome da pessoa e o nome da profissão. Ensaie teacher/nurse/driver com pausas naturais, sem transformar todos os sons em sílabas portuguesas.',
 pitfall='Work pode ser verbo ou nome; aqui as fichas usam work como trabalhar e job como posto contável. Não chamar toda ocupação docente de professor em inglês.'),
 dict(id='LEX-A1-03',title='Organizar o dia sem trocar os horários',after='A1-02',words=['get up','wake up','have breakfast','start','finish','usually'],
 situation='A recebe rotina: wake up 6h; get up 6h30; have breakfast 7h; start work 8h; finish work 16h; usually walk home. B recebe: wake up 7h; get up 8h; have breakfast 8h15; start work 9h; finish work 17h; usually walk home. Perguntem What time do you…? e anotem duas diferenças. Explique a outra dupla em português qual dado é começo do expediente e qual é sair da cama. Apoios: six thirty = 6h30; eight fifteen = 8h15; four/five in the afternoon = 16h/17h.',
 result='A acorda antes de levantar e começa trabalho às 8h; B levanta às 8h e começa às 9h. Usar usually walk home não elimina exceções. Modelo: I wake up at six, but I get up at six thirty. I have breakfast at seven. I start work at eight and finish at four in the afternoon. I usually walk home.',
 phon='Destaque o horário que contrasta, mantendo get up separado de wake up. O interlocutor devolve cada campo, em vez de confirmar tudo com yes.',
 pitfall='Não tratar wake up e get up como sinônimos. Um erro ao converter 16h não é automaticamente erro no significado de finish.'),
 dict(id='LEX-A1-04',title='Entender uma descrição de moradia',after='A1-03',words=['kitchen','bedroom','bathroom','flat','rent'],
 situation='A anuncia: We rent a flat. Two bedrooms, one kitchen, one bathroom. B procura apartamento com dois quartos e pergunta Are there two bedrooms? / Is there a bathroom?. A confirma a composição; B desenha uma planta esquemática e escreve a descrição. Depois troquem com um apartamento de um quarto, uma cozinha e um banheiro. O objetivo é entender o anúncio, não negociar um contrato.',
 result='Primeiro flat: dois bedrooms, uma kitchen e um bathroom; segundo flat: um bedroom. Rent descreve alugar, não comprar. Modelo: We rent a flat. There are two bedrooms. There is a kitchen and a bathroom. Não inferir tamanho, preço ou regras que não aparecem.',
 phon='Ouça bedroom e bathroom e associe ao cômodo correto. Se confundir, confirme a função em português antes de voltar ao inglês.',
 pitfall='Room é genérico; bedroom é quarto de dormir. Não apresentar as descrições fictícias como aconselhamento imobiliário ou características universais de apartamentos.'),
 dict(id='LEX-A1-05',title='Encontrar o serviço certo',after='A1-03',words=['library','bookshop','bus stop','next to','opposite'],
 situation='Desenhe norte [A Library][B Café]; sul [C Bookshop][D Bus stop], com A em frente a C e B em frente a D. A vê o mapa; B recebe grade vazia. A localiza library next to café, bookshop opposite library e bus stop next to bookshop. B coloca etiquetas e escolhe o local indicado por A para comprar um livro. Troquem papéis com library e bookshop trocadas, preservando as relações do novo mapa.',
 result='Primeiro mapa: biblioteca A; livraria C; ponto D. Para compra no cenário, bookshop C. O segundo mapa precisa ser recalculado; não repetir automaticamente a letra C. Modelo: The bookshop is opposite the library. The bus stop is next to the bookshop.',
 phon='Compare library e bookshop em mensagens de destino; a resposta útil é chegar ao serviço certo. Não confiar apenas na semelhança gráfica com livraria.',
 pitfall='Opposite usa lados opostos; next to usa vizinhança. Bus stop não é automaticamente um terminal rodoviário.'),
 dict(id='LEX-A1-06',title='Refeição e preços com critério explícito',after='A1-04',words=['rice','egg','milk','meal','price','cheap','expensive'],
 situation='Planejem a compra fictícia para uma meal: arroz, dois ovos e leite. Loja A: bag of rice 3, egg 1 cada, bottle of milk 2. Loja B: rice 5, egg 2 cada, milk 4. A conhece A, B conhece B. Perguntem price e registrem os dois totais. Para esta personagem, total até 7 é cheap; acima de 9 é expensive. Expliquem qual compra cabe nos 8 créditos disponíveis. O cardápio não é recomendação alimentar.',
 result='Loja A: 3+2+2=7, classificada cheap e cabe em 8. Loja B: 5+4+4=13, expensive segundo o critério fornecido e não cabe. Modelo: We need rice, two eggs and milk for a meal. What is the price? The meal ingredients cost seven credits (os ingredientes custam sete créditos). Usar frase de custo como apoio receptivo, não novo alvo gramatical.',
 phon='Na escuta dos preços, confirmar cada produto e quantidade separadamente. Eggs precisa continuar reconhecível mesmo com pausa antes do número.',
 pitfall='Cheap/expensive dependem do critério; não medir situação econômica real do estudante. Meal não é meat; contar pacotes de rice e garrafas de milk.'),
 dict(id='LEX-A1-07',title='Convidar e escolher uma atividade',after='A1-08',words=['walk','watch','free [gratuito]','free [disponível]','rain','cold','meet','invite'],
 situation='A convida B para uma walk no parque sábado às 10h. A caminhada é free; B está free nesse horário. B informa previsão do cartão: rain e cold. Os dois escolhem watch a film no centro às 10h; ingresso de 2 créditos, portanto não gratuito. Escrevam confirmação de onde vão meet e invite uma terceira pessoa com Would you like to join us?. Não registrem aceitação da terceira pessoa sem resposta. Apoios: community centre = centro comunitário; ticket = ingresso; forecast = previsão; no exercício use It’s going to rain como bloco de apoio.',
 result='Primeiro plano: caminhada gratuita, disponibilidade de B. Plano final: filme no centro, sábado 10h, preço 2; B continua disponível, mas o evento final não é gratuito. Modelo: Are you free on Saturday? Let’s watch a film at the community centre. The film isn’t free. We’re going to meet at ten. Would you like to join us? O convite à terceira pessoa fica sem confirmação.',
 phon='O ouvinte restitui horário, preço e atividade. Free sozinho não basta para dizer se a mensagem trata de preço ou agenda; preserve a frase de contexto.',
 pitfall='Rain/cold são dados fictícios do cartão, não previsão meteorológica atual. Invite não implica confirmação; meet exige encontro, não só envio de mensagem.')
]

GROUPS += [
 dict(id='LEX-A1-08',title='Contar uma rotina e combinar tarefas',after='A1-02',words=['have lunch','have dinner','go to bed','take a shower','cook','clean'],situation='Cartão de Ana: almoço ao meio-dia, jantar às 19h, cama às 22h; banho pela manhã; cozinha sábado, limpa cozinha sexta. Cartão de Rui: almoço às 13h, jantar às 20h, cama às 23h; banho à noite; cozinha sexta, limpa cozinha sábado. Use apoio de horas: twelve = 12h; one = 13h neste contexto; seven = 19h; eight = 20h; ten = 22h; eleven = 23h. Perguntem What time do you have lunch/dinner? e When do you cook/clean? com traduções. Cada um fala com I; destinatário anota três diferenças. Depois combinem quem cozinha sexta e quem limpa sábado sem mudar cartões silenciosamente. Dividir em refeições/horários e ações/dias se necessário.',result='Ana almoça 12h e Rui 13h; jantares 19h/20h; camas 22h/23h. Rui já cozinha sexta e limpa sábado no cartão. Se negociar alteração, confirmá-la explicitamente. Modelo: I have lunch at twelve. I take a shower in the morning. I cook on Saturdays. Rui: I have dinner at eight and go to bed at eleven. Não concluir que quem vai para cama às 23h dorme exatamente às 23h.',phon='O parceiro distingue lunch/dinner e número de hora antes de anotar. Repetição permitida; fornecer twelve/eleven como apoio antes da escuta. Registro de horário por leitura não comprova escuta.',pitfall='Não impor horários ideais de sono/refeição nem solicitar rotina pessoal. Have a shower é alternativa válida a take a shower. Retomar breakfast/get up/wake up sem contabilizá-los como novas entradas. Na produção inicial com I, não exigir terceira pessoa antes de revisar o padrão.'),
 dict(id='LEX-A1-09',title='Ler um anúncio e localizar itens numa moradia',after='A1-03',words=['living room','garden','window','bed','fridge','washing machine'],situation='Dois anúncios fictícios: A, apartamento com sala e quarto; cama no quarto, geladeira e máquina de lavar na cozinha, sem jardim. B, casa com sala e jardim; cama no quarto, geladeira na cozinha, sem máquina de lavar. Nos dois, há cadeira ao lado da janela da sala. A precisa de máquina; B prefere jardim. Distribuam anúncios em cartões separados e perguntem Is there a garden/a washing machine? Where is the bed/fridge? Apoio: sofa = sofá, house = casa, flat = apartamento, no garden = sem jardim. Escolham para a necessidade de cada personagem; não inventem preço ou qualidade.',result='Apartamento A atende necessidade de máquina; casa B tem jardim. The bed is in the bedroom. The fridge is in the kitchen. The chair is next to the window in the living room. There is a washing machine in flat A; there isn’t one in house B. As preferências não tornam uma opção universalmente melhor. O leitor deve localizar objeto e cômodo separadamente.',phon='Contraste bed / bedroom e living room / kitchen em frases. O ouvinte monta tabela Objeto/Cômodo, pedindo repetição. Não exigir definição inglesa de cada objeto antes de usar apoio português.',pitfall='Textos são anúncios fictícios, sem oferta real. Não inferir que casa tem jardim ou que toda cozinha tem máquina. Diferenciar informação ausente de negativa explícita: aqui ausências de jardim/máquina estão declaradas. Retomar mother/father ou outros itens não é necessário para descrever moradia.'),
 dict(id='LEX-A1-10',title='Escolher roupa, confirmar tamanho e perguntar sobre pagamento',after='A1-04',words=['shirt','trousers','shoes','size','try on','pay'],situation='Loja fictícia: camisa azul tamanho M, camisa vermelha tamanho L; calça preta tamanho M; sapatos brancos tamanho 38. Cartão do cliente: quer camisa azul M e experimentar antes de decidir. Vendedor pode oferecer as peças disponíveis; pagamento com cartão é aceito. Apoios: medium = M; large = L; thirty-eight = 38, apenas reconhecimento do cartão; size = tamanho; by card = com cartão. Cliente pergunta Can I try it on?; depois pergunta Can I pay by card? Não realizar compra real. Segunda rodada: cliente quer sapatos e pergunta Can I try them on?; vendedor confirma par e tamanho. Separar experimentação, decisão e pergunta de pagamento.',result='Camisa azul M, não vermelha L. Can I try it on? refere-se à camisa singular; Can I try them on? aos sapatos. What size? — Medium / size M. Can I pay by card? pergunta possibilidade; não significa que pagou ou concluiu compra. These trousers are black e These shoes are white usam plural no bloco fornecido.',phon='Ouça BLUE shirt / RED shirt e M / L com confirmação. Pratique try IT on / try THEM on e peça ao parceiro identificar objeto. Para 38, ler cartão com apoio, sem tratar como domínio de todos os números maiores.',pitfall='Não supor equivalência de tamanhos internacionais. Trousers mantém forma plural no padrão; pants é variante americana válida nesse sentido. Não cobrar tamanho pessoal do aluno, usar personagem. Retomar cores e price/free sem contar como nova aprendizagem lexical completa.'),
 dict(id='LEX-A1-11',title='Conferir transporte e seguir um trajeto curto',after='A1-03',words=['ticket','station','train','bus','turn left','turn right'],situation='Cartões de transporte: Ana vai ao trabalho de trem; Rui vai à escola de ônibus. Ana quer passagem para Central; Rui encontra colega no ponto de ônibus, não na estação. Depois use mapa textual com orientação fixa: “Você sai pela porta da biblioteca olhando para a praça. Virar à sua esquerda leva à estação. Virar à sua direita leva ao ponto de ônibus.” B recebe destino estação; A dá Turn left at the library. Nova rodada destino ponto de ônibus: Turn right at the library. Não mudar orientação inicial. Apoio: ticket = passagem; station = estação; train = trem; bus = ônibus; left = esquerda; right = direita; Central é nome do destino fictício.',result='I go to work by train. I go to school by bus. A ticket to Central, please. Estação e ponto são lugares distintos. Com a orientação dada, esquerda → estação; direita → ponto. O destinatário restitui destino e direção antes de simular movimento. Não inventar horário ou linha de transporte.',phon='Leia left/right em instrução completa e peça ao ouvinte explicar direção em português. Alternar destinos, mantendo orientação explícita. Sem voz, tarefa é leitura de trajeto, não compreensão auditiva.',pitfall='Mapa textual permite trabalho sem imagem; tarefa pode ser feita sem deslocamento corporal. Não exigir navegação real nem conhecimento de cidade. Retomar bus stop, library, at school/at work do percurso anterior. Ticket aqui é transporte e train é substantivo, não outros sentidos.')
]

GROUPS += [{'id': 'LEX-A1-12',
  'title': 'Contar sentimentos e primeiras impressões',
  'after': 'A1-05',
  'words': ['angry', 'worried', 'excited', 'bored', 'friendly', 'shy'],
  'situation': 'Cartões: Ana está preocupada com teste amanhã; Rui animado com passeio sábado; Jo zangado '
               'com barulho agora; Lee entediado na espera. Kim diz “I feel shy with new people”; Nara '
               'cumprimenta cordialmente e oferece ajuda. Em duas rodadas, A representa dois personagens e B '
               'preenche Nome/Como se sente/Motivo informado. Apoio: about = com/em relação a; noise = '
               'barulho; test = teste; trip = passeio/viagem. Depois comparem impressão de Nara (“She seems '
               'friendly”) e declaração de Kim (“Kim says: I feel shy”). Não identificar sentimento só por '
               'silêncio.',
  'result': 'I’m worried about the test. I’m excited about the trip. I’m angry about the noise. I’m bored. '
            'Kim se autodescreve shy; Nara parece friendly pelo comportamento descrito, sem provar amizade '
            'íntima. The wait is boring / I’m bored pode ser usado como contraste com tradução. Motivos não '
            'informados não devem ser inventados.',
  'phon': 'Contraste angry e hungry, retomando pré-A1 com significado antes de ensaio oral. Ouça '
          'bored/boring em frase, marcando pessoa e atividade. Não exigir perfeição sonora para registrar '
          'informação recuperada.',
  'pitfall': 'Some tarefas permitem opinião, outras pedem fonte. Ensinar seems e says como apoios, sem '
             'obrigar nova teoria gramatical. Excited neste uso é expectativa animada. Dividir seis entradas '
             'em três pares se necessário.'}]

